<script setup lang="ts">
import { onMounted,ref } from 'vue';
import { request,errorMessage } from '@/services/api';
type Application={id:number;organization:string;siteName:string;siteType:string;address:string;contactEmail:string;contactPhone:string;relationship:string;adminFirstName:string;adminLastName:string;adminEmail:string;adminPhone:string;status:string;message:string|null;siteId:number|null};
const applications=ref<Application[]>([]);const reason=ref('');const error=ref('');const busy=ref(false);const invitation=ref('');
async function load(){try{applications.value=await request('/api/admin/site-applications');}catch(e){error.value=errorMessage(e);}}
async function decide(id:number,decision:string){busy.value=true;error.value='';try{await request(`/api/admin/site-applications/${id}/decision`,{method:'POST',body:JSON.stringify({decision,reason:reason.value})});reason.value='';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function setup(id:number){busy.value=true;error.value='';invitation.value='';try{const result=await request<{setupToken:string;expiresAt:string}>(`/api/admin/site-applications/${id}/setup-invitation`,{method:'POST'});invitation.value=`Setup token: ${result.setupToken}\nExpires: ${result.expiresAt}\nDeliver privately to the proposed site administrator for /setup-site-admin. No email has been sent. Issuing again invalidates earlier tokens.`;}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="dashboard-card live-page site-applications"><h1>Site applications</h1><p>Review organization authority and the proposed administrator before approval. The applicant and proposed administrator may be different people.</p><p v-if="error" role="alert">{{ error }}</p><pre v-if="invitation" role="status" style="white-space:pre-wrap">{{ invitation }}</pre><label>Decision reason or requested information<textarea v-model="reason" maxlength="2000" /></label>
<article v-for="item in applications" :key="item.id" class="dashboard-card application-card"><h2>{{ item.siteName }} — {{ item.status }}</h2><p>{{ item.organization }} · {{ item.siteType }} · {{ item.address }}</p><p>Applicant: {{ item.contactEmail }} · {{ item.contactPhone }} · {{ item.relationship }}</p><p>Proposed administrator: {{ item.adminFirstName }} {{ item.adminLastName }} · {{ item.adminEmail }} · {{ item.adminPhone }}</p><p>{{ item.message }}</p><div v-if="item.status==='pending'" class="action-row"><button type="button" class="report-issue-button" :disabled="busy || !reason.trim()" @click="decide(item.id,'approve')">Approve site #{{ item.id }}</button><button type="button" class="action-link" :disabled="busy || !reason.trim()" @click="decide(item.id,'request_information')">Request information #{{ item.id }}</button><button type="button" class="action-link" :disabled="busy || !reason.trim()" @click="decide(item.id,'reject')">Reject site #{{ item.id }}</button></div><button type="button" class="action-link" v-if="item.status==='approved'" :disabled="busy" @click="setup(item.id)">Issue administrator setup token #{{ item.id }}</button></article><p v-if="!applications.length">No site applications.</p></section></template>

<style scoped>
.site-applications{display:grid;gap:24px}.site-applications>h1{font-size:28px;font-weight:750}.site-applications p{font-size:14px;line-height:1.7;overflow-wrap:anywhere}.site-applications>label{display:grid;gap:8px;font-size:14px;font-weight:600}.site-applications textarea{width:100%;min-height:100px;padding:12px;border:1px solid var(--product-border);border-radius:10px;background:var(--product-surface);font-weight:400}.application-card{display:grid;gap:16px}.application-card h2{font-size:20px;font-weight:700;line-height:1.4}.application-card>.action-link{justify-self:start}.site-applications pre{padding:16px;border:1px solid var(--product-border);border-radius:10px;overflow-wrap:anywhere}
</style>
